#include "mesh.h"#include "FileStuff.h"#define		kPutIt		1#define		kRaiseIt	2#define		kLowerIt	3#define		kSmoothIt	4#define		kZeroIt		5void changeElevation ( FSSpec theMeshFSSpec, int theFunction );long doDialog( short newDialog );void changeElevation ( FSSpec theMeshFSSpec, int theFunction ){//----------------------------------vars--------------------------------------------------	short		theMeshFileRef;	Str255		theNewFileName = "\p:mesh.out:mesh";	Str255		theBackupFileName = "\p:mesh.old";	const short rChangeInputDialog = 131;	OSErr		theError;	long adjustment = 0;	int x, y;	int theWest, theEast, theNorth, theSouth, theNWest, theNEast, theSWest, theSEast;	long meshSize, meshWidth, meshHeight;	struct meshHeader theMeshHeader;	gridData *theGrid, *theTempGrid;//----------------------------------------------------------------------------------------		if ( theFunction != kZeroIt && theFunction != kSmoothIt )		adjustment =  doDialog( rChangeInputDialog );	theError = FSpOpenDF ( &theMeshFSSpec, fsCurPerm, &theMeshFileRef );	if ( theError != noErr ){		ParamText( "\pCan't open mesh file.", "\p", "\p", "\p" );		StopAlert ( 400, nil );		ExitToShell();	}	FileRead ( &theMeshHeader, sizeof(struct meshHeader), theMeshFileRef );	meshWidth = theMeshHeader.meshWidth * 16;	meshHeight = theMeshHeader.meshHeight * 16;	meshSize =  meshWidth * meshHeight;	theGrid = (struct gridData *) NewPtr (meshSize * sizeof(gridData));	FileRead(theGrid, theMeshHeader.meshLength, theMeshFileRef);	switch ( theFunction ){		case kRaiseIt:			for ( y = 0; y < meshHeight * meshWidth; y += meshWidth )				for ( x = 0; x < meshWidth; x++ )					theGrid[x + y].height += adjustment;		break;		case kLowerIt:			for ( y = 0; y < meshHeight * meshWidth; y += meshWidth )				for ( x = 0; x < meshWidth; x++ )					theGrid[x + y].height -= adjustment;		break;		case kSmoothIt:			theTempGrid = (struct gridData *) NewPtr (meshSize * sizeof(gridData));			for ( y = meshWidth; y < ((meshHeight - 1) * meshWidth); y += meshWidth )				for ( x = 1; x < (meshWidth - 1); x++ ){						theWest = (x - 1) + y;						theEast = (x + 1) + y;						theNorth = x + (y - meshWidth);						theSouth = x + (y + meshWidth);						theNWest = (x - 1) + (y - meshWidth);						theNEast = (x + 1) + (y - meshWidth);						theSWest = (x - 1) + (y + meshWidth);						theSEast = (x + 1) + (y + meshWidth);						theTempGrid[ x + y].height =	(	theGrid[theWest].height +															theGrid[theEast].height +															theGrid[theNorth].height +															theGrid[theSouth].height +															theGrid[theNWest].height +															theGrid[theNEast].height +															theGrid[theSWest].height +															theGrid[theSEast].height ) / 8;				}															// now copy it back			for ( y = meshWidth; y < ((meshHeight - 1) * meshWidth); y += meshWidth )				for ( x = 1; x < (meshWidth - 1); x++ )					theGrid[ x + y].height = theTempGrid[ x + y].height;			DisposePtr ( (Ptr) theTempGrid );		break;		case kZeroIt:			for ( y = 0; y < meshHeight * meshWidth; y += meshWidth )				for ( x = 0; x < meshWidth; x++ )					theGrid[x + y].height = 0;		break;	}	FileSeek ( theMeshFileRef, 1088L );	FileWrite (theGrid, theMeshHeader.meshLength, theMeshFileRef);	DisposePtr ( (Ptr) theGrid );	FSClose ( theMeshFileRef );}